CREATE TABLE "__temp__students" ("id" integer primary key autoincrement not null, "student_name" varchar not null, "gender" varchar not null, "learners_lin" varchar, "learners_nin" varchar, "date_of_birth" date not null, "religion" varchar, "mobile_number" varchar, "email" varchar, "district_of_birth" varchar, "previous_school" varchar, "ple_index_number" varchar, "special_issue" text, "ple_english" varchar, "ple_mathematics" varchar, "ple_sst" varchar, "ple_science" varchar, "ple_total" integer, "ple_aggregates" integer, "pass_slip_path" varchar, "father_full_name" varchar, "father_mobile_number" varchar, "father_email" varchar, "father_nin" varchar, "father_physical_address" varchar, "father_occupation" varchar, "father_dead_alive" varchar, "mother_full_name" varchar, "mother_mobile_number" varchar, "mother_email" varchar, "mother_nin" varchar, "mother_physical_address" varchar, "mother_occupation" varchar, "mother_dead_alive" varchar, "guardian_full_name" varchar, "guardian_mobile_number" varchar, "guardian_email" varchar, "guardian_nin" varchar, "guardian_physical_address" varchar, "guardian_occupation" varchar, "guardian_relationship" varchar, "official_comment" text, "level" varchar, "created_at" datetime, "updated_at" datetime, "class" varchar, "stream" varchar, "district" varchar, "nationality" varchar, "tribe" varchar, "medical_status" varchar not null default ('Healthy'), "physical_health" varchar not null default ('Fit'), "photo_path" varchar, "admission_number" varchar not null, "father_passport_photo_path" varchar, "mother_passport_photo_path" varchar, "guardian_passport_photo_path" varchar) ;
CREATE TABLE "academics" ("id" integer primary key autoincrement not null, "name" varchar, "description" text, "created_at" datetime, "updated_at" datetime) ;
CREATE TABLE "alevel_subjects" ("id" integer primary key autoincrement not null, "academics_id" integer, "subject_name" varchar not null, "subject_code" varchar, "stream" varchar check ("stream" in ('arts', 'science', 'general')) not null default 'general', "category" varchar check ("category" in ('principal', 'subsidiary', 'general')) not null default 'principal', "classes" text, "created_at" datetime, "updated_at" datetime, foreign key("academics_id") references "academics"("id") on delete set null) ;
CREATE TABLE "alumnis" ("id" integer primary key autoincrement not null, "student_name" varchar not null, "photo_path" varchar, "gender" varchar not null, "learners_lin" varchar, "learners_nin" varchar, "date_of_birth" date not null, "religion" varchar, "mobile_number" varchar, "email" varchar, "district_of_birth" varchar, "district" varchar, "nationality" varchar, "tribe" varchar, "previous_school" varchar, "ple_index_number" varchar, "uce_index_number" varchar, "special_issue" text, "ple_english" varchar, "ple_mathematics" varchar, "ple_sst" varchar, "ple_science" varchar, "ple_total" integer, "ple_aggregates" integer, "uce_english" varchar, "uce_mathematics" varchar, "uce_physics" varchar, "uce_chemistry" varchar, "uce_biology" varchar, "uce_history" varchar, "uce_geography" varchar, "uce_economics" varchar, "uce_literature" varchar, "uce_other" varchar, "combination" varchar, "pass_slip_path" varchar, "medical_status" varchar not null default 'Healthy', "physical_health" varchar not null default 'Fit', "father_full_name" varchar, "father_mobile_number" varchar, "father_email" varchar, "father_nin" varchar, "father_physical_address" varchar, "father_occupation" varchar, "father_dead_alive" varchar, "mother_full_name" varchar, "mother_mobile_number" varchar, "mother_email" varchar, "mother_nin" varchar, "mother_physical_address" varchar, "mother_occupation" varchar, "mother_dead_alive" varchar, "guardian_full_name" varchar, "guardian_mobile_number" varchar, "guardian_email" varchar, "guardian_nin" varchar, "guardian_physical_address" varchar, "guardian_occupation" varchar, "guardian_relationship" varchar, "official_comment" text, "level" varchar, "graduation_class" varchar not null, "graduation_year" integer not null, "stream" varchar, "student_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "students"("id") on delete set null) ;
CREATE TABLE "attendance" ("id" integer primary key autoincrement not null, "attendance_date" date not null, "class" varchar not null, "stream" varchar, "present_count" integer not null, "absent_count" integer not null, "total_students" integer not null, "term" varchar not null, "academic_year" varchar not null, "remarks" text, "created_at" datetime, "updated_at" datetime) ;
CREATE TABLE "bookmarks" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime) ;
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key")) ;
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key")) ;
CREATE TABLE "counselling_tracks" ("id" integer primary key autoincrement not null, "student_id" integer not null, "counselling_type" varchar not null, "date_of_session" date not null, "notes" text, "outcome" text, "status" varchar not null default ('ongoing'), "counsellor_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("counsellor_id") references staff("id") on delete set null on update no action) ;
CREATE TABLE "discipline_records" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime) ;
CREATE TABLE "discipline_tracks" ("id" integer primary key autoincrement not null, "student_id" integer not null, "case_name" varchar not null, "disciplinary_action" varchar not null, "resolution" varchar, "case_status" varchar not null default ('pending'), "date_of_incident" date, "description" text, "recorded_by" integer, "created_at" datetime, "updated_at" datetime, "attachments" text, "statement_type" varchar, foreign key("recorded_by") references staff("id") on delete set null on update no action) ;
CREATE TABLE "emergency_contacts" ("id" integer primary key autoincrement not null, "user_id" integer, "contact_type" varchar not null, "contact_value" varchar not null, "user_name" varchar, "user_email" varchar, "message" text, "status" varchar not null default 'pending', "contacted_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null) ;
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP) ;
CREATE TABLE "faqs" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime) ;
CREATE TABLE "feedback" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "category" varchar not null, "priority" varchar not null default 'medium', "subject" varchar not null, "message" text not null, "attachments" text, "status" varchar not null default 'open', "admin_response" text, "responded_at" datetime, "responded_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("responded_by") references "users"("id") on delete set null) ;
CREATE TABLE "grades" ("id" integer primary key autoincrement not null, "student_id" integer not null, "subject" varchar not null, "term" varchar not null, "academic_year" varchar not null, "score" numeric not null, "grade_letter" varchar, "remarks" text, "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "students"("id") on delete cascade) ;
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id")) ;
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null) ;
CREATE TABLE "marks_entries" ("id" integer primary key autoincrement not null, "student_id" integer not null, "teacher_subject_id" integer not null, "academics_id" integer, "olevel_subject_id" integer, "alevel_subject_id" integer, "level" varchar not null, "class" varchar not null, "stream" varchar, "term" varchar, "academic_year" integer, "entry_type" varchar not null, "activity_number" integer, "test_number" integer, "theory_marks" numeric, "practical_marks" numeric, "total_marks" numeric, "grade" varchar, "created_by" integer not null, "entered_at" datetime, "created_at" datetime, "updated_at" datetime, "uace_points" integer, "is_principal_subject" tinyint(1) default '1', foreign key("teacher_subject_id") references teacher_subjects("id") on delete cascade on update no action, foreign key("academics_id") references academics("id") on delete set null on update no action, foreign key("olevel_subject_id") references olevel_subjects("id") on delete set null on update no action, foreign key("alevel_subject_id") references alevel_subjects("id") on delete set null on update no action, foreign key("created_by") references staff("id") on delete cascade on update no action) ;
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null) ;
CREATE TABLE "olevel_subjects" ("id" integer primary key autoincrement not null, "academics_id" integer, "subject_name" varchar not null, "subject_code" varchar, "category" varchar check ("category" in ('general', 'optional')) not null default 'general', "classes" text, "requires_practical" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("academics_id") references "academics"("id") on delete set null) ;
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email")) ;
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id")) ;
CREATE TABLE "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "category" varchar not null default 'general', "type" varchar not null default 'string', "description" text, "created_at" datetime, "updated_at" datetime) ;
CREATE TABLE sqlite_sequence(name,seq) ;
CREATE TABLE "staff" ("id" integer primary key autoincrement not null, "surname" varchar not null, "first_name" varchar not null, "other_name" varchar, "sex" varchar not null, "date_of_birth" date not null, "uts_file_no" varchar, "district_file_no" varchar, "computer_no" varchar, "national_id_no" varchar, "registration_no" varchar, "salary_scale" varchar, "gross_salary" numeric, "net_salary" numeric, "tin_no" varchar, "date_of_1st_appt" date, "designation_of_1st_appt" varchar, "minute_no_1st_appt" varchar, "date_of_current_appt" date, "designation_of_current_appt" varchar, "minute_no_current_appt" varchar, "date_of_confirmation" date, "minute_no_confirmation" varchar, "date_of_current_posting" date, "teaching_subjects" varchar, "telephone_contacts" varchar, "marital_status" varchar, "next_of_kin" varchar, "next_of_kin_telephone" varchar, "email" varchar, "other_academic_qualifications" text, "highest_level_of_education" varchar, "created_at" datetime, "updated_at" datetime, "ipps_no" varchar, "staff_type" varchar not null default 'private', "hire_date" date, "role" varchar not null default 'teacher', "gender" varchar not null default 'Male', "employment_type" varchar not null default 'Regular', "department" varchar not null default 'General', "medical_status" varchar not null default 'Healthy', "physical_health" varchar not null default 'Fit', "photo_path" varchar, "religion" varchar, "password" varchar, "enable_teacher_login" tinyint(1) not null default '0', "last_teacher_login_at" datetime, "staff_designation" varchar check ("staff_designation" in ('HEADMASTER', 'DEPUTY HEADMASTER-ADMINISTRATION', 'DEPUTY HEADMASTER-ACADEMICS', 'DEPUTY HEADMASTER-DISCIPLINE', 'DIRECTOR OF STUDIES', 'DEAN OF STUDENTS', 'SCHOOL-COUNSELOR', 'DISCIPLINARY OFFICER', 'CLASS TEACHER', 'PREFECT PATRON', 'WARDEN', 'HEAD OF DEPARTMENT', 'LAB TECHNICIAN', 'LIBRARY OFFICER'))) ;
CREATE TABLE "student_optional_subjects" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime, "student_id" integer not null, "olevel_subject_id" integer, "alevel_subject_id" integer, "level" varchar not null, "stream" varchar, foreign key("olevel_subject_id") references olevel_subjects("id") on delete cascade on update no action, foreign key("alevel_subject_id") references alevel_subjects("id") on delete cascade on update no action) ;
CREATE TABLE "student_performances" ("id" integer primary key autoincrement not null, "student_id" varchar not null, "olevel_subject_id" integer, "alevel_subject_id" integer, "level" varchar check ("level" in ('olevel', 'alevel')) not null, "class" varchar not null, "stream" varchar, "academic_year" varchar not null, "term" varchar, "average_marks" numeric not null default '0', "highest_marks" numeric, "lowest_marks" numeric, "performance_trend" numeric not null default '0', "grade" varchar, "created_at" datetime, "updated_at" datetime, "uace_points" integer, "subject_category" varchar check ("subject_category" in ('principal', 'subsidiary', 'general')), foreign key("student_id") references "students"("admission_number") on delete cascade, foreign key("olevel_subject_id") references "olevel_subjects"("id") on delete set null, foreign key("alevel_subject_id") references "alevel_subjects"("id") on delete set null) ;
CREATE TABLE "students" ("id" integer primary key autoincrement not null, "student_name" varchar not null, "gender" varchar not null, "learners_lin" varchar, "learners_nin" varchar, "date_of_birth" date not null, "religion" varchar, "mobile_number" varchar, "email" varchar, "district_of_birth" varchar, "previous_school" varchar, "ple_index_number" varchar, "special_issue" text, "ple_english" varchar, "ple_mathematics" varchar, "ple_sst" varchar, "ple_science" varchar, "ple_total" integer, "ple_aggregates" integer, "pass_slip_path" varchar, "father_full_name" varchar, "father_mobile_number" varchar, "father_email" varchar, "father_nin" varchar, "father_physical_address" varchar, "father_occupation" varchar, "father_dead_alive" varchar, "mother_full_name" varchar, "mother_mobile_number" varchar, "mother_email" varchar, "mother_nin" varchar, "mother_physical_address" varchar, "mother_occupation" varchar, "mother_dead_alive" varchar, "guardian_full_name" varchar, "guardian_mobile_number" varchar, "guardian_email" varchar, "guardian_nin" varchar, "guardian_physical_address" varchar, "guardian_occupation" varchar, "guardian_relationship" varchar, "official_comment" text, "level" varchar, "created_at" datetime, "updated_at" datetime, "class" varchar, "stream" varchar, "district" varchar, "nationality" varchar, "tribe" varchar, "medical_status" varchar not null default 'Healthy', "physical_health" varchar not null default 'Fit', "photo_path" varchar, "admission_number" varchar, "father_passport_photo_path" varchar, "mother_passport_photo_path" varchar, "guardian_passport_photo_path" varchar, "promoted_at" datetime, "promotion_count" integer not null default '0') ;
CREATE TABLE "support_tickets" ("id" integer primary key autoincrement not null, "ticket_number" varchar not null, "user_id" integer, "name" varchar not null, "email" varchar not null, "category" varchar not null, "priority" varchar not null default 'medium', "subject" varchar not null, "description" text not null, "status" varchar not null default 'open', "attachments" text, "assigned_to" integer, "resolution" text, "resolved_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, foreign key("assigned_to") references "users"("id") on delete set null) ;
CREATE TABLE "teacher_subjects" ("id" integer primary key autoincrement not null, "staff_id" integer not null, "academics_id" integer, "olevel_subject_id" integer, "alevel_subject_id" integer, "level" varchar check ("level" in ('olevel', 'alevel')) not null default 'olevel', "specialty" varchar check ("specialty" in ('arts', 'science')), "classes" text, "created_at" datetime, "updated_at" datetime, "streams" text, foreign key("staff_id") references "staff"("id") on delete cascade, foreign key("academics_id") references "academics"("id") on delete set null, foreign key("olevel_subject_id") references "olevel_subjects"("id") on delete set null, foreign key("alevel_subject_id") references "alevel_subjects"("id") on delete set null) ;
CREATE TABLE "user_preferences" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime, "user_id" integer not null, "key" varchar not null, "value" text, foreign key("user_id") references "users"("id") on delete cascade) ;
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'user', "phone" varchar, "address" text, "bio" text, "avatar" varchar, "status" varchar not null default 'active', "last_login_at" datetime, "last_login_ip" varchar) ;
